import { GrammarParseError } from '../utils/errors/grammarParseError.js';
import { isWordChar } from './isWordChar.js';
import { parseChar } from './parseChar.js';
import { parseName } from './parseName.js';
import { parseSpace } from './parseSpace.js';
import { SymbolIds } from './symbolIds.js';
import { InternalRuleDef, InternalRuleType } from './types.js';

const WHITESPACE = /\s/;

export class RulesBuilder {
  public pos = 0;
  public readonly symbolIds = new SymbolIds();
  // a sparse list, indexed by rule id; `null` marks a rule that was never defined
  public readonly rules: (InternalRuleDef[] | null)[] = [];
  public readonly src: string;

  private readonly start: number;
  private readonly timeLimit: number;

  public constructor(src: string, limit = 1000) {
    this.src = src;
    this.start = Date.now();
    this.timeLimit = limit;
    this.parse(src);
  }

  private at(pos: number): string {
    return pos >= 0 && pos < this.src.length ? this.src[pos] : '';
  }

  private parse(src: string): void {
    // move cursor forward until we reach non-whitespace content
    this.pos = parseSpace(src, 0, true);

    while (this.pos < src.length) {
      this.parseRule(src);
    }

    // Validate the state to ensure that all rules are defined
    for (const rule of this.rules) {
      if (rule === null) {
        continue;
      }
      for (const elem of rule) {
        if (elem.type === InternalRuleType.RULE_REF) {
          // Ensure that the rule at that location exists
          const value = elem.value as number;
          const referenced = value < this.rules.length ? this.rules[value] : null;
          const ruleExists = value < this.rules.length && Boolean(referenced);
          if (!ruleExists) {
            const missingRuleName = this.symbolIds.reverseGet(value);
            let missingRulePos = this.symbolIds.getPos(missingRuleName);

            // Skip over the ::= and any whitespace
            while (
              missingRulePos < src.length &&
              ([':', '='].includes(src[missingRulePos]) ||
                WHITESPACE.test(src[missingRulePos]))
            ) {
              missingRulePos += 1;
            }

            throw new GrammarParseError(
              src,
              missingRulePos,
